$money = static fn (float $value): string => ($value < 0 ? '-Rp' : 'Rp') . number_format(abs($value), 0, ',', '.');
$manualAccounts = array_values(array_filter($accounts, static fn (array $account): bool => (bool) $account['allow_manual'] && (bool) $account['is_active']));
$assetAccounts = array_values(array_filter($accounts, static fn (array $account): bool => $account['account_type'] === 'asset' && (bool) $account['is_active']));
$openingCreditAccounts = array_values(array_filter($accounts, static fn (array $account): bool => in_array($account['account_type'], ['liability', 'equity'], true) && (bool) $account['is_active']));
$typeLabels = ['asset' => 'Aset', 'liability' => 'Liabilitas', 'equity' => 'Ekuitas', 'revenue' => 'Pendapatan', 'contra_revenue' => 'Kontra pendapatan', 'expense' => 'Beban'];
$sourceLabels = ['sale' => 'Penjualan', 'goods_receipt' => 'Penerimaan stok', 'refund' => 'Refund', 'expense' => 'Pengeluaran', 'stock_opname' => 'Stok opname', 'shift_opening' => 'Modal shift', 'manual_journal' => 'Jurnal manual', 'opening_balance' => 'Saldo awal'];
$trialDebit = array_sum(array_map(static fn (array $row): float => (float) $row['debit'], $trialBalance));
$trialCredit = array_sum(array_map(static fn (array $row): float => (float) $row['credit'], $trialBalance));
$selectedAccount = array_values(array_filter($accounts, static fn (array $account): bool => (int) $account['id'] === (int) $selectedAccountId))[0] ?? null;
?>

